/**
 * Character identity graph (server only).
 * - Identity and aliases come from edutext (identity.json, generated by scripts/sync-edutext-identity.py).
 * - One person = one page: a registry person linked to a hand-written Wiki entry never gets a second page.
 * - Links: unambiguous name mentions in Wiki text, backlinks, and nearest neighbours in the current state.
 */
import { ALL_ENTRIES } from "@/domains/wiki/wiki.data"
import { computeNow, phaseAt, type Person, type State } from "@/app/wiki/state/living-model.mjs"
import registry from "@/app/wiki/state/registry.json"
import identity from "@/app/wiki/state/identity.json"

interface IdentityPerson { call: string; first: string; nickname: string; last: string; firstEn: string; nicknameEn: string; lastEn: string; aliases: string[] }
interface IdentityFile { source: string; people: Record<string, IdentityPerson>; wiki: Record<string, { ids: string[]; method: string; note?: string }> }
const ID = identity as IdentityFile

export const IDENTITY_SOURCE = ID.source
export const roster: Person[] = registry.people
const personById = new Map(roster.map((p) => [p.id, p]))
export const active = roster.filter((p) => p.status === "current")
const activeIndex = new Map(active.map((p, i) => [p.id, i]))
const characterEntries = ALL_ENTRIES.filter((e) => e.category === "キャラクター")
const entryById = new Map(ALL_ENTRIES.map((e) => [e.id as string, e]))

/** Registry ID → owning Wiki entry, and Wiki entry → registry IDs (one entry may describe a duo). */
export const ownerOf = new Map<string, string>()
export const membersOf = new Map<string, string[]>()
for (const [wikiId, link] of Object.entries(ID.wiki)) {
  if (!entryById.has(wikiId)) continue
  membersOf.set(wikiId, link.ids)
  for (const c of link.ids) ownerOf.set(c, wikiId)
}
/** Canonical page ID for any registry or Wiki ID. */
export const pageOf = (id: string) => ownerOf.get(id) ?? id

export interface PageRef { id: string; name: string; nameEn: string }
const registryPages: PageRef[] = roster.filter((p) => !ownerOf.has(p.id)).map((p) => ({ id: p.id, name: p.name || p.formal, nameEn: p.nameEn || p.formalEn }))
const wikiPages: PageRef[] = characterEntries.map((e) => ({ id: e.id, name: e.name, nameEn: e.nameEn ?? "" }))
export const pages: PageRef[] = [...wikiPages, ...registryPages]
const pageById = new Map(pages.map((p) => [p.id, p]))

// ── Mention index: aliases that resolve to exactly one page ─────────────
const isLatin = (s: string) => /^[\x20-\x7e]+$/.test(s)
const usable = (s: string) => (isLatin(s) ? s.replace(/[^a-z]/gi, "").length >= 5 && /\s/.test(s.trim()) : s.length >= 3)
const aliasOwners = new Map<string, Set<string>>()
const addAlias = (alias: string, page: string) => {
  const a = alias.trim()
  if (!a || !usable(a)) return
  const k = isLatin(a) ? a.toLowerCase() : a
  aliasOwners.set(k, (aliasOwners.get(k) ?? new Set()).add(page))
}
for (const e of characterEntries) { addAlias(e.name, e.id); if (e.nameEn) addAlias(e.nameEn, e.id) }
for (const [cid, p] of Object.entries(ID.people)) {
  const page = pageOf(cid)
  // Single given names are too ambiguous in prose; use full names and single-name characters only.
  const singleName = !p.last
  for (const a of p.aliases) if (singleName || /[・\s]/.test(a) || a === p.call) addAlias(a, page)
}
const buckets = new Map<string, { alias: string; page: string; latin: boolean }[]>()
for (const [alias, owners] of aliasOwners) {
  if (owners.size !== 1) continue
  const latin = isLatin(alias)
  const key = alias[0] ?? ""
  const list = buckets.get(key) ?? []
  list.push({ alias, page: [...owners][0]!, latin })
  buckets.set(key, list)
}
for (const list of buckets.values()) list.sort((a, b) => b.alias.length - a.alias.length)

/** Pages mentioned in a text (greedy longest match, Latin names need word boundaries). */
export function mentionsIn(text: string, self: string): string[] {
  const found = new Set<string>()
  const lower = text.toLowerCase()
  for (let i = 0; i < text.length; i++) {
    const list = (buckets.get(text[i]!) ?? []).concat(buckets.get(lower[i]!) ?? [])
    for (const c of list) {
      const hay = c.latin ? lower : text
      if (!hay.startsWith(c.alias, i)) continue
      if (c.latin && (/[a-z]/i.test(text[i - 1] ?? "") || /[a-z]/i.test(text[i + c.alias.length] ?? ""))) continue
      if (c.page !== self) found.add(c.page)
      i += c.alias.length - 1
      break
    }
  }
  return [...found]
}
let linkCache: { out: Map<string, string[]>; back: Map<string, string[]> } | null = null
export function links() {
  if (linkCache) return linkCache
  const out = new Map<string, string[]>(), back = new Map<string, string[]>()
  for (const e of ALL_ENTRIES) {
    const ids = mentionsIn(e.description + "\n" + (e.descriptionEn ?? ""), e.id)
    out.set(e.id, ids)
    for (const t of ids) back.set(t, [...(back.get(t) ?? []), e.id])
  }
  linkCache = { out, back }
  return linkCache
}
export const ref = (id: string): PageRef => pageById.get(id) ?? { id, name: entryById.get(id)?.name ?? id, nameEn: entryById.get(id)?.nameEn ?? "" }

// ── Current state (today only), cached per day ──────────────────────────
/** Present only: the state is solved for today's environment, no time evolution. Cached per UTC day. */
export const today = () => phaseAt(new Date()).day
let cache: { day: number; current: State[] } | null = null
export function currentStates() {
  const day = today()
  if (cache?.day !== day) cache = { day, current: computeNow(active, new Date()).states }
  return cache
}
export const stateOf = (cid: string): State | undefined => {
  const i = activeIndex.get(cid)
  return i === undefined ? undefined : currentStates().current[i]
}
export const person = (cid: string) => personById.get(cid)
export const nickname = (cid: string) => ID.people[cid]
export const macroRegion = (region: string) => { const r = region.replace(/\s*\(.*\)\s*$/, ""); return (/^Gigapolis/i.test(r) ? "Gigapolis" : /^Crescent/i.test(r) ? "Crescent" : /^Granbell/i.test(r) ? "Granbell" : /AURALIS/i.test(r) ? "AURALIS" : r || "Unspecified") }
